{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Eluxadoline, the closest analogue (Morgan 0.2772), has an absolute oral bioavailability of 1.02% in humans, driven by very low gastrointestinal permeability (2.3%) and moderate first-pass extraction; its large, polar, ionizable structure with multiple amide/carboxylate groups parallels the query's high TPSA, HBD count, and anionic character, supporting F <20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Rigosertib, which shares a carboxylic acid, methoxyphenyl, and polar aniline-like framework with the query, had only 13.9% absolute oral bioavailability in the fed state and is clinically characterized as having low oral availability requiring IV infusion; this supports low F for a similarly polar, ionizable molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Terameprocol, containing dimethoxyphenyl groups like the query, showed approximately 2% absolute oral bioavailability in patients, demonstrating that aromatic ether-rich structures can still have very poor oral absorption when other physicochemical barriers dominate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Almorexant, a dimethoxyphenyl-containing drug with amide-like polar functionality, had an absolute oral bioavailability of 11.2% (90% CI 9.6-13.1), below the 20% threshold, due to poor absorption and/or extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Revefenacin, a large polar amide/carbamate with very low oral bioavailability (<3%), supports that high molecular weight and high polar surface area in this structural class lead to F <20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Moexipril, a dimethoxyphenyl-containing ACE inhibitor prodrug, has an oral bioavailability of 22%, just above the threshold; however, it is an ester prodrug with lower MW/TPSA, limiting transfer to the non-prodrug, more polar query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is a large (MW 592), highly polar (TPSA 155 Å²), fully ionized carboxylic acid with 4 HBD and 7 HBA, and the closest experimental analogues—eluxadoline, terameprocol, almorexant, revefenacin, and fed-state rigosertib—all show F <20%; high-F analogues are less transferable because they are ester prodrugs or basic amines.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query; all analogues have low Morgan similarity (0.24-0.28), so transferability is limited.",
    "Food effects and formulation are unknown; rigosertib shows F 35% fasting vs 13.9% fed, so prandial state could shift a borderline compound.",
    "No permeability, efflux, or solubility measurements for the query; the prior is physicochemical only."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

